SELECT sd.*,
       h.name AS hospitalName,
       d.name AS departmentName
FROM setmeal_detail sd
LEFT JOIN hospital h ON sd.hospital_id = h.id
LEFT JOIN department d ON sd.department_id = d.id


        AND sd.setmeal_id = #{setmealId}


        AND sd.hospital_id = #{hospitalId}


        AND sd.department_id = #{departmentId}


        AND sd.package_type = #{packageType}


        AND sd.status = #{status}


        AND (sd.name LIKE CONCAT('%',#{keyword},'%') OR sd.description LIKE CONCAT('%',#{keyword},'%'))

